CREATE TABLE "public"."event_rule" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "created_at" timestamp with time zone DEFAULT now(),
    "user_id" bigint NOT NULL,
    -- matching fields (AND for a single row, OR across rows)
    "series" text,
    "name" text,
    "invitees" text[],
    "invitee_domain" text,
    "calendar_id" bigint,
    "internal" event_internal,
    "type" event_type,
    -- overrides
    "category_id" bigint
);

CREATE UNIQUE INDEX event_rule_pkey ON public.event_rule USING btree (id);

ALTER TABLE "public"."event_rule"
    ADD CONSTRAINT "event_rule_pkey" PRIMARY KEY USING INDEX "event_rule_pkey";

ALTER TABLE "public"."event_rule"
    ADD CONSTRAINT "event_rule_user_id_fkey" FOREIGN KEY (user_id) REFERENCES "user" (id) ON DELETE CASCADE NOT valid;

ALTER TABLE "public"."event_rule" validate CONSTRAINT "event_rule_user_id_fkey";

CREATE INDEX event_rule_user_id_key ON public.event_rule USING btree (user_id);

ALTER publication supabase_realtime
    ADD TABLE public.event_rule;

ALTER TABLE "public"."event_rule"
    ADD CONSTRAINT "event_rule_category_id_fkey" FOREIGN KEY (category_id) REFERENCES category (id) ON DELETE CASCADE NOT valid;

ALTER TABLE "public"."event_rule" validate CONSTRAINT "event_rule_category_id_fkey";

ALTER TABLE "public"."event_rule"
    ADD CONSTRAINT "event_rule_calendar_id_fkey" FOREIGN KEY (calendar_id) REFERENCES calendar (id) ON DELETE CASCADE NOT valid;

ALTER TABLE "public"."event_rule" validate CONSTRAINT "event_rule_calendar_id_fkey";

ALTER TABLE public.event_rule
    ADD CONSTRAINT event_rule_unique_constraint UNIQUE (user_id, series, name, invitees, invitee_domain, calendar_id, internal, type);

